#!/usr/bin/env node
/* wampo — THE COMMITTED `sec-tickers.js` WAS GENERATED BY THE COMMITTED CODE.
 * 2026-10-11.
 *
 * `sec-tickers.js` is a GENERATED asset whose generator was wired into no
 * workflow, so the table could sit beside code that did not produce it — and
 * the failure is SILENT, because the table only ever fills a blank: a ship that
 * moves a name withholds its own gains and no reader, count or diff says a
 * word. `stamp-assets.mjs --check` is blind to it by construction, the stamp
 * being a hash of the asset's own content.
 *
 * This asserts the one thing that is both cheap and exact: the fingerprint of
 * OUR CODE stamped into the asset equals the fingerprint of the code that is
 * committed. It runs in milliseconds and reads no registry and no store, so it
 * cannot redden when `sec-funds.json` grows or when the pipeline commits a
 * filing — which is the property that disqualified `gen-sec-tickers --check`
 * (that one compares asset BYTES, and the asset's header interpolates the
 * registry's row count and four store-derived figures).
 *
 * WHAT IT DOES NOT CLAIM. A moved fingerprint does not prove a key would move;
 * it proves the answer is no longer known. Clearing it is one regeneration,
 * whose own diff says whether anything moved — and that regeneration absorbs
 * any registry or store drift at the same time, which is why the trigger is
 * the change that makes it necessary rather than a clock.
 *
 * CONTROLS. Every condition this gate rests on has a case that can fail it, and
 * the suite EXITS 1 IF A MUTATION PASSES:
 *   - one mutation per hashed input, so a forgotten input fails BY NAME;
 *   - app.js edited INSIDE the slice must move the value and OUTSIDE must not,
 *     which is the whole reason the gate is quiet on 57 of 70 commits;
 *   - a perturbed `sec-funds.json` and a perturbed store must NOT move it,
 *     which is CI-safety against registry drift asserted rather than promised.
 */
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, copyFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { codeFingerprint, assetFingerprint, CODE_INPUTS, CODE_LINE_RE } from "./lib-sec-fingerprint.mjs";

/* import.meta.url, never a hardcoded sandbox path: `cwd: "/home/user/no-app"`
 * in map-test.mjs reported `spawn python3 ENOENT` and hid ten red runs, and
 * `fund-note-test.mjs` went red on its first CI run for the same reason. */
const ROOT = new URL("..", import.meta.url).pathname.replace(/\/$/, "");
const ASSET = `${ROOT}/sec-tickers.js`;

let fail = 0;
const ok = (c, what, detail = "") => {
  if (c) console.log(`  ok    ${what}${detail ? "  — " + detail : ""}`);
  else { console.error(`  FAIL  ${what}${detail ? "  — " + detail : ""}`); fail++; }
};

console.log("sec-tickers-stamp-test: the table was generated by the committed code\n");

/* ---------- 1. the gate itself ---------- */
if (!existsSync(ASSET)) { console.error(`FAIL: ${ASSET} does not exist`); process.exit(1); }
const stamped = assetFingerprint(ASSET);
const { fp: live, parts } = codeFingerprint();

ok(stamped !== null, "the asset carries a SEC_TICKERS_CODE stamp",
  stamped === null ? "no `const SEC_TICKERS_CODE = \"...\";` line — regenerate with scripts/gen-sec-tickers.mjs" : stamped.slice(0, 22) + "…");

if (stamped !== null && stamped !== live) {
  console.error(`\n  FAIL  sec-tickers.js is STALE: it was generated by DIFFERENT CODE than is committed.`);
  console.error(`        stamped in the asset : ${stamped}`);
  console.error(`        the committed code   : ${live}`);
  console.error(`\n        Per-input hashes now (the asset does not record these, so compare against`);
  console.error(`        the last regenerating commit to see which moved):`);
  for (const [k, v] of Object.entries(parts)) console.error(`          ${k.padEnd(32)} ${v}`);
  console.error(`\n        A resolver, a name cleaner or the generator moved and the table was not`);
  console.error(`        regenerated, so every key that change would add is silently withheld.`);
  console.error(`        FIX: node scripts/gen-sec-tickers.mjs && node scripts/stamp-assets.mjs`);
  console.error(`        and commit sec-tickers.js + index.html in the SAME commit. Read the`);
  console.error(`        ADDED/REMOVED/CHANGED report `+"`gen-sec-tickers.mjs --check`"+` prints first.`);
  fail++;
} else if (stamped !== null) {
  ok(true, "the stamp matches the committed code", live.slice(0, 22) + "…");
}

/* ---------- 2. a scratch tree, so every control can perturb an input ---------- */
const TMP = mkdtempSync(`${tmpdir()}/wampo-secfp-`);
mkdirSync(`${TMP}/scripts`, { recursive: true });
const SURFACE = ["app.js", "fund-er.js"];
for (const rel of [...SURFACE, ...CODE_INPUTS]) copyFileSync(`${ROOT}/${rel}`, `${TMP}/${rel}`);
const baseline = codeFingerprint({ root: TMP }).fp;
ok(baseline === live, "a byte-identical copy of the tree fingerprints identically",
  baseline === live ? "" : `${baseline} vs ${live}`);

const touch = (rel, mutate) => {
  const orig = readFileSync(`${ROOT}/${rel}`, "utf8");
  writeFileSync(`${TMP}/${rel}`, mutate(orig));
  const got = codeFingerprint({ root: TMP }).fp;
  writeFileSync(`${TMP}/${rel}`, orig);
  return got;
};
/* a comment line is enough and is honest: the fingerprint's claim is "this is
 * not the code the table was built from", and a comment IS different code. */
const commentAtEnd = (s) => s + "\n/* wampo stamp-test mutation */\n";

/* THE EXPECTED INPUT LIST IS FROZEN HERE AND NOT READ FROM `CODE_INPUTS`, and
 * that is the whole difference between a control and a decoration. My first
 * version looped over `CODE_INPUTS` itself, and running the suite against a
 * fingerprint module with `match-sec-tickers.mjs` DELETED from that list left
 * every control passing — because the loop simply stopped testing the input
 * that had gone missing. *A control derived from the thing it is checking
 * cannot see that thing shrink.* Frozen, a removal fails twice: the set
 * comparison below names it, and its own mutation control stops moving the
 * value. An ADDITION fails too, so a new input cannot arrive untested. */
const EXPECTED_INPUTS = [
  "scripts/match-sec-tickers.mjs",
  "scripts/lib-af-abbrev.mjs",
  "scripts/gen-sec-tickers.mjs",
  "scripts/lib-ledger.mjs",
  "scripts/lib-schema.mjs",
  "scripts/apppath.mjs",
];
{
  const a = JSON.stringify([...CODE_INPUTS].sort()), b = JSON.stringify([...EXPECTED_INPUTS].sort());
  ok(a === b, "the hashed input list is the one this suite has a control for",
    a === b ? `${CODE_INPUTS.length} inputs` : `CODE_INPUTS=${a} expected=${b} — add or remove the matching control`);
}

/* ---------- 3. ONE MUTATION PER HASHED INPUT, failing by name ---------- */
console.log("\n  mutation controls — perturbing each hashed input MUST move the value:");
for (const rel of EXPECTED_INPUTS) {
  const got = touch(rel, commentAtEnd);
  ok(got !== baseline, `mutating ${rel} moves the fingerprint`,
    got === baseline ? "IT DID NOT — this input is hashed in name only and a change to it would ship silently" : "");
}

/* the app.js / fund-er.js surface, which comes from the slice rather than the
 * file, so it gets BOTH directions */
{
  const got = touch("fund-er.js", commentAtEnd);
  ok(got !== baseline, "mutating fund-er.js moves the fingerprint",
    got === baseline ? "IT DID NOT — fund-er.js is in the slice and a resolver widening would ship silently" : "");
}
{
  /* INSIDE the slice: a line immediately after the prologue's first statement,
   * which `apppath.mjs` takes as its head marker. */
  const head = "  const $ = (id) => document.getElementById(id);";
  const got = touch("app.js", (s) => {
    if (!s.includes(head)) throw new Error("stamp-test: app.js's prologue head marker moved — the control cannot be built");
    return s.replace(head, head + "\n  /* wampo stamp-test mutation */");
  });
  ok(got !== baseline, "editing app.js INSIDE the resolver slice moves the fingerprint",
    got === baseline ? "IT DID NOT — the slice is not being hashed and a cleanFiledName change would ship silently" : "");
}
{
  /* OUTSIDE the slice. THIS IS THE CONTROL THAT MAKES THE GATE QUIET: app.js
   * is 5,348 lines and only the resolver surface can move a key, so a template,
   * a formatter or a map edit must not redden a gate on every frontend push. */
  const got = touch("app.js", commentAtEnd);
  ok(got === baseline, "editing app.js OUTSIDE the slice leaves the fingerprint alone",
    got === baseline ? "" : "IT MOVED — the whole file is being hashed, and this gate will redden on frontend edits that cannot move a key");
}

/* ---------- 4. CI-SAFETY AGAINST DRIFT, asserted and not promised ---------- */
console.log("\n  drift controls — the external inputs MUST NOT move the value:");
for (const rel of ["sec-funds.json", "plans-all.json", "lineups-index.json"]) {
  if (!existsSync(`${ROOT}/${rel}`)) { ok(false, `${rel} is present to be perturbed`); continue; }
  /* a file the fingerprint must not read. It is written into the scratch tree
   * MUTATED; if the implementation ever reaches for it, the value moves and
   * this control fails — which is the only way the claim can be tested. */
  writeFileSync(`${TMP}/${rel}`, JSON.stringify({ wampo: "stamp-test perturbation", funds: [], plans: [] }));
  const got = codeFingerprint({ root: TMP }).fp;
  ok(got === baseline, `a perturbed ${rel} leaves the fingerprint alone`,
    got === baseline ? "" : "IT MOVED — this gate will redden when an external source refreshes with no defect present");
}
/* and the store itself */
{
  mkdirSync(`${TMP}/data/lineups`, { recursive: true });
  writeFileSync(`${TMP}/data/lineups/00.json`, JSON.stringify({ wampo: "stamp-test perturbation" }));
  const got = codeFingerprint({ root: TMP }).fp;
  ok(got === baseline, "a perturbed lineup shard leaves the fingerprint alone",
    got === baseline ? "" : "IT MOVED — an hourly data commit would redden this gate");
}

/* ---------- 5. labelled invariants ---------- */
console.log("\n  invariants:");
/* DELIBERATE ABSENCE, not an oversight. CLAUDE.md names lib-disclose.mjs as one
 * of five files that can stale the table. It is not an input: neither the
 * generator nor apppath imports it, and the suppressors it owns reach the table
 * only through app.js's GENERATED TWIN, which is inside the slice. Hashing it
 * as well would redden on its arms that gate `er` alone and can move no key.
 * If that ever changes, this assertion is the thing that must be edited. */
ok(!CODE_INPUTS.includes("scripts/lib-disclose.mjs"),
  "lib-disclose.mjs is NOT hashed (it reaches the table only via app.js's twin, which is in the slice)");
ok(!CODE_INPUTS.includes("sec-tickers.js") && !CODE_INPUTS.includes("sec-funds.json"),
  "neither the asset nor the registry is hashed (the first would be self-referential, the second would redden on a refresh)");
ok(CODE_LINE_RE.test(`const SEC_TICKERS_CODE = "sha256:abc123";`),
  "the marker expression the generator writes is the one this test reads");
{
  /* the stamp must be the LAST thing a regeneration changes if nothing else
   * moved — i.e. it must be present exactly once, so a second copy cannot be
   * read in preference to the live one. */
  const n = (readFileSync(ASSET, "utf8").match(/^const SEC_TICKERS_CODE = /gm) || []).length;
  ok(n === 1, "the asset carries exactly one SEC_TICKERS_CODE line", `found ${n}`);
}

console.log(fail ? `\nsec-tickers-stamp-test: ${fail} FAILURE(S)` : `\nsec-tickers-stamp-test: all checks passed`);
process.exit(fail ? 1 : 0);
